<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {api,formatTime,inspectionControlApi,postInspectionControl} from '../api';
import {preferences} from '../composables/preferences';
import {registerPageRefresher} from '../composables/pageRefresh';
import {pointLabel,readingLabel,readingValue,badgeColor,clock} from '../composables/presentation';
import {missionProgress,missionStartup} from '../composables/mission';
import {inspectionTask,taskPhotos} from '../composables/inspectionState';
const target=new URLSearchParams(location.hash.split('?')[1]||''),targetMap=target.get('map_id')||'';
const progress=ref(null),progressReceivedAt=ref(0),assets=ref(null),selectedSession=ref(target.get('session')||''),fullMap=ref(preferences.mapRange==='full'),error=ref(''),photoOpen=ref(false),selectedPhoto=ref(null),control=ref(null),controlBusy=ref(false),controlMessage=ref(''),pendingTask=ref(null);let poll,unregister,loading=false,assetsLoading=null,controlLoading=false,disposed=false,lastAssetsVersion='',lastControlAt=0,preparedMap='';
const task=computed(()=>inspectionTask(assets.value,progress.value,selectedSession.value,pendingTask.value)),mission=computed(()=>missionProgress(task.value)),percent=computed(()=>mission.value.percent);
const trajectory=computed(()=>{const saved=assets.value?.trajectory;return saved&&saved.task_id===task.value?.task_id?saved:null;});
const livePose=computed(()=>!selectedSession.value&&task.value?.task_id===progress.value?.task_id?progress.value?.live_pose:null);
const liveTrack=computed(()=>!selectedSession.value&&task.value?.task_id===progress.value?.task_id?{task_id:progress.value?.task_id,map_id:progress.value?.map_id,points:progress.value?.live_track||[]}:null);
const taskActive=computed(()=>['running','active','in_progress','localizing','finishing'].includes(String(task.value?.state||'').toLowerCase()));
const canStart=computed(()=>!controlBusy.value&&!selectedSession.value&&!taskActive.value&&control.value?.can_start===true);
const canCancel=computed(()=>!controlBusy.value&&control.value?.can_cancel===true);
const points=computed(()=>(assets.value?.map?.points||[]).filter(p=>!/^ORIGIN/.test(p.name))),photos=computed(()=>taskPhotos(assets.value,task.value));
const rows=computed(()=>points.value.map(p=>{const photo=photos.value.filter(r=>r.waypoint===p.name).at(-1);return{...p,photo,label:readingLabel(photo),value:photo?.value==null?(readingLabel(photo)==='识别失败'?'识别失败':'未记录'):readingValue(photo.value)};}));
const steps=computed(()=>{const startup=missionStartup(task.value);return [startup,...(task.value?.route||['A','B','C','ORIGIN']).map(id=>{const step=task.value?.steps?.find(s=>s.id===id),row=rows.value.find(p=>p.name===id),done=step?.status==='done',active=startup.done&&id===mission.value.stage&&['running','active','in_progress'].includes(task.value?.state),failed=['failed','error'].includes(step?.status);return{id,title:id==='ORIGIN'?'返回起点':row?.display_name||pointLabel(id),done,active,failed:row?.label==='识别失败'||failed,label:row?.label==='识别失败'?'识别失败':failed?(id==='ORIGIN'?'返航失败':'巡检异常'):done?'已完成':active?'进行中':'待执行',description:failed?(task.value?.failure_reason||'该点位未能完成，请检查设备。'):row?.photo?clock(row.photo.captured_at)+' · '+row.label:done?'已确认到达':active?'正在前往该点位':'等待任务推进'};})];});
async function loadAssets(){if(assetsLoading||disposed)return assetsLoading;const session=selectedSession.value,version=assetsVersion();assetsLoading=(async()=>{try{const query=new URLSearchParams();if(session)query.set('session',session);if(targetMap)query.set('map_id',targetMap);const next=await api('/api/inspection-assets'+(query.size?'?'+query:''),{timeoutMs:8000});if(disposed||session!==selectedSession.value)return;assets.value=next;lastAssetsVersion=version;error.value='';prepareNavigation();}catch(e){if(!disposed)error.value=e.message||'巡检记录读取失败，请重试。';}finally{assetsLoading=null;if(!disposed&&session!==selectedSession.value)void loadAssets();}})();return assetsLoading;}
watch(selectedSession,()=>{if(assets.value)assets.value={map:assets.value.map,sessions:assets.value.sessions};lastAssetsVersion='';void loadAssets();});
function assetVersion(value){return JSON.stringify([value?.task_id,value?.state,value?.current_step_id,value?.steps?.map(s=>[s.id,s.status,s.at]),value?.evidence?.photo_count,value?.event_revision]);}
function assetsVersion(){return JSON.stringify([selectedSession.value,targetMap,assetVersion(progress.value)]);}
async function load(){if(disposed||loading||(document.hidden&&preferences.pauseBackground))return;loading=true;try{const next=await api('/inspection-progress.json?latest=1',{timeoutMs:2500});if(disposed)return;progress.value=next;progressReceivedAt.value=Date.now();if(error.value==='任务进度读取失败，请重试。')error.value='';if(!assets.value||assetsVersion()!==lastAssetsVersion)void loadAssets();}catch{if(!disposed)error.value='任务进度读取失败，请重试。';}finally{loading=false;}}
async function loadControl(){if(disposed||controlLoading||(document.hidden&&preferences.pauseBackground))return;controlLoading=true;lastControlAt=Date.now();try{const next=await inspectionControlApi('/api/inspection-control',{timeoutMs:2500});if(!disposed)control.value=next;}catch{if(!disposed)control.value={can_start:false,can_cancel:false,error:'巡检控制暂不可用，请刷新后重试。'};}finally{controlLoading=false;}}
async function prepareNavigation(){const mapId=assets.value?.map?.id;if(selectedSession.value||!mapId||preparedMap===mapId||control.value?.can_start!==true)return;preparedMap=mapId;try{await postInspectionControl('/api/inspection-control',{action:'prepare',map_id:mapId});}catch{/* Actual start retains every readiness check. */}}
async function inspectionAction(action){if(controlBusy.value)return;controlBusy.value=true;controlMessage.value='';try{const body={action};if(action==='start')body.map_id=assets.value?.map?.id;else body.task_id=control.value?.task_id;const result=await postInspectionControl('/api/inspection-control',body);control.value=result;if(action==='start'&&result.task_id)pendingTask.value={task_id:result.task_id,map_id:body.map_id,state:'running',state_text:'启动检查中',started_at:Date.now()/1000,route:task.value?.route||['A','B','C','ORIGIN'],steps:[]};controlMessage.value=action==='start'?'巡检请求已接收，正在检查硬件与定位。':'已发送安全停止请求，等待小车完成停车。';await load();await loadControl();}catch(e){controlMessage.value=e.message|| (action==='start'?'巡检启动失败，请检查设备状态。':'取消请求失败，请检查任务状态。');await loadControl();}finally{controlBusy.value=false;}}
const failureMessage=computed(()=>['failed','error','startup_failed'].includes(task.value?.state)?task.value?.failure_reason||'巡检未能完成，请到 RVBench 检查设备与定位状态。':'');
const feedbackMessage=computed(()=>failureMessage.value||control.value?.error||(control.value?.state==='stopping'?'小车正在执行安全停车，请稍候。':controlMessage.value));
const feedbackError=computed(()=>Boolean(failureMessage.value||control.value?.error)||(Boolean(controlMessage.value)&&!controlMessage.value.includes('已接收')&&!controlMessage.value.includes('已发送')));
function openBench(){document.dispatchEvent(new CustomEvent('studio-page-change',{detail:{page:'devices'}}));}
function showPhoto(photo){selectedPhoto.value=photo;photoOpen.value=true;}
onMounted(async()=>{poll=setInterval(()=>{void load();if(Date.now()-lastControlAt>=3000)void loadControl();},1000);unregister=registerPageRefresher('inspection',async()=>{await Promise.all([load(),loadControl()]);});await Promise.all([load(),loadControl()]);await loadAssets();if(disposed)return;prepareNavigation();const photo=target.get('photo'),waypoint=target.get('waypoint');if(photo||waypoint){const match=photos.value.find(row=>photo?row.scene_url===photo:row.waypoint===waypoint);if(match)showPhoto(match);else error.value='关联的采集图片暂未找到，请刷新后重试。';}});onBeforeUnmount(()=>{disposed=true;clearInterval(poll);unregister?.();});
</script>
<template><div class="split-map">
 <UiCard title="巡检路线" glyph="map" class="map-panel"><div class="card-content"><div class="map-toolbar"><span>{{assets?.map?.name||'巡检地图'}}</span><button class="btn" @click="fullMap=!fullMap"><UiIcon name="map" :size="15"/>{{fullMap?'仅看任务区域':'展开完整地图'}}</button></div><div class="map-stage" :class="{full:fullMap}"><div class="map-main">
 <TaskMap controls :map="assets?.map" :route="task?.route||[]" :progress="preferences.routeAnimation?percent:null" :task-key="task?.task_id" :live-pose="livePose" :live-track="liveTrack" :trajectory="trajectory" :status-at="progressReceivedAt" :moving="taskActive&&Boolean(task?.startup?.first_motion_at||percent>0)" :full="fullMap"/>
 </div></div><div class="map-legend"><span><i class="legend-node"></i>巡检点位</span><span><i class="legend-line"></i>任务路线</span></div><div class="map-table"><div class="section-label">本次巡检读数</div><table><thead><tr><th>点位</th><th>仪表名称</th><th>读数</th><th>识别结果</th><th>采集时间</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.name"><td>{{pointLabel(p.name)}}</td><td>{{p.display_name||pointLabel(p.name)}}</td><td :class="badgeColor(p.label)">{{p.value}}</td><td><span class="badge" :class="badgeColor(p.label)">{{p.label}}</span></td><td class="number">{{p.photo?clock(p.photo.captured_at):'—'}}</td><td><button class="btn plain" :disabled="!p.photo" @click="showPhoto(p.photo)"><UiIcon name="eye" :size="15"/>查看</button></td></tr></tbody></table><div v-if="error" class="field-error">{{error}}</div></div></div></UiCard>
 <UiCard title="任务进展" glyph="route" class="form-panel"><div class="card-content"><div class="field"><select id="session" v-model="selectedSession" aria-label="巡检记录选择"><option value="">当前 / 最近任务</option><option v-for="session in assets?.sessions||[]" :key="session" :value="session">{{session.slice(0,4)}}-{{session.slice(4,6)}}-{{session.slice(6,8)}} {{session.slice(9,11)}}:{{session.slice(11,13)}}</option></select></div><div class="inspection-controls" aria-label="巡检控制"><button class="btn primary" type="button" :disabled="!canStart" :aria-busy="controlBusy" @click="inspectionAction('start')"><UiIcon name="route" :size="15"/>{{controlBusy?'正在提交…':'开始巡检'}}</button><button class="btn danger" type="button" :disabled="!canCancel" :aria-busy="controlBusy" @click="inspectionAction('cancel')"><UiIcon name="x" :size="15"/>{{controlBusy?'正在处理…':'取消巡检'}}</button></div><div v-if="feedbackMessage" class="inspection-control-message" :class="{'is-error':feedbackError}" :role="feedbackError?'alert':'status'" aria-live="polite"><UiIcon v-if="feedbackError" name="alert" :size="15"/><span>{{feedbackMessage}}</span><button v-if="failureMessage" type="button" class="btn plain" @click="openBench">查看设备状态<UiIcon name="arrow" :size="13"/></button></div><div class="patrol-summary"><div><b class="number">{{task?Math.round(percent):'—'}}<small v-if="task">%</small></b><div class="subtle">已到达 {{mission.arrived}} / {{mission.route.length}} 个点位</div></div><span class="badge" :class="badgeColor(task?.state_text||'')">{{task?.state_text||(selectedSession?'历史照片':'等待任务')}}</span></div><div class="progress-bar" role="progressbar" :aria-valuenow="percent" aria-valuemin="0" aria-valuemax="100" aria-label="实际任务进度"><span :style="{width:percent+'%'}"></span></div><div class="patrol-times"><span>{{task?.started_at?clock(task.started_at)+' 开始':'等待巡检任务'}}</span><span>{{task?.duration_s||task?.elapsed_s?'用时 '+Math.round((task.duration_s||task.elapsed_s)/60)+' 分钟':''}}</span></div><div class="timeline"><div v-for="(step,index) in steps" :key="step.id" class="timeline-item"><span class="timeline-dot" :class="{done:step.done,current:step.active,failed:step.failed}">{{step.failed?'×':step.done?'✓':index+1}}</span><div class="timeline-content"><div class="timeline-top"><b>{{step.title}}</b><span class="badge" :class="step.failed?'red':step.active?'blue':badgeColor(step.label)">{{step.label}}</span></div><small>{{step.description}}</small></div></div></div></div></UiCard>
</div>
<UiModal v-model="photoOpen" title="巡检采集图片" width="min(850px,92vw)"><template v-if="selectedPhoto"><img class="photo-dialog-img" :src="selectedPhoto.scene_url" alt="巡检现场采集图片"><div class="detail-strip"><span>{{pointLabel(selectedPhoto.waypoint)}} · {{clock(selectedPhoto.captured_at)}}</span><span class="badge" :class="badgeColor(readingLabel(selectedPhoto))">{{readingLabel(selectedPhoto)}}</span></div></template></UiModal></template>
